<script setup lang="ts">
import PageHeader from '../workspace/PageHeader.vue'
import {onMounted,ref} from 'vue'
import {api} from '../api'
import {useRequestScope} from '../platform/request-scope'
import {messages as t} from './locale'
import ProductNav from './ProductNav.vue'
import {operationKey,completeOperation} from './operation-key'
import type {ProductWallet,CatalogProduct,ProductOrder,ProductAccount} from './types'
const wallet=ref<ProductWallet>(),products=ref<CatalogProduct[]>([]),admin=ref(false),code=ref(''),invite=ref(''),error=ref(''),notice=ref(''),busy=ref(false),capture=useRequestScope()
const dates=(value:string)=>new Date(value).toLocaleString('zh-CN')
const stateName=(value:string)=>({pending:'等待支付',checkout_ready:'收银台已准备',paid:'已核验支付',checkout_unknown:'建单结果待核查',review:'需要人工核查'} as Record<string,string>)[value]||value
const sourceName=(value:string)=>({admin:'内测发放',card:'兑换卡',payment:'已核验收款',waffo:'订阅支付'} as Record<string,string>)[value]||value
async function load(){const scope=capture();try{const [value,catalog,profile]=await Promise.all([api<ProductWallet>('/product/wallet'),api<{items:CatalogProduct[]}>('/product/catalog'),api<ProductAccount>('/product/account')]);if(scope.valid()){wallet.value=value;products.value=catalog.items;admin.value=profile.role==='ADMIN'}}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function action(path:string,body?:unknown){const scope=capture();busy.value=true;error.value='';notice.value='';try{const result=await api<Record<string,unknown>>(path,{method:'POST',body});if(!scope.valid())return;notice.value=result.reason?String(result.reason):'操作已完成';await load()}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function purchase(product:CatalogProduct){if(!confirm(`购买“${product.title}”，${product.currency} ${(product.amountMinor/100).toFixed(2)}？`))return;const scope=capture();busy.value=true;error.value='';try{const prior=wallet.value?.orders.find(o=>o.product.sku===product.sku&&['pending','checkout_ready','checkout_unknown','review'].includes(o.state));const order=prior||await api<ProductOrder>('/product/orders',{method:'POST',body:{productId:product.id,requestKey:operationKey('purchase:'+product.id)}});if(!scope.valid())return;const checkout=await api<ProductOrder>('/product/orders/'+order.id+'/checkout',{method:'POST'});if(!scope.valid())return;completeOperation('purchase:'+product.id);notice.value='订单已保存，请从订单列表打开收银台。支付完成后查询订单状态。';if(checkout.checkoutUrl)await load()}catch(e){if(scope.valid()){error.value=(e as Error).message;await load()}}finally{if(scope.valid())busy.value=false}}
function cancel(order:ProductOrder){if(confirm('停止这个订单的自动续费？已确认的本期权益保留到期。'))void action('/product/orders/'+order.id+'/cancel-renewal')}
onMounted(load)
</script>
<template><div class="product-page"><PageHeader :title="t.wallet" description="查看积分、会员权益与每一笔使用记录。"><button :disabled="busy" @click="load">{{t.refresh}}</button></PageHeader><ProductNav :admin="admin"/><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="product-hint" role="status">{{notice}}</p><template v-if="wallet"><div class="product-metrics"><div class="product-metric">{{t.available}}<strong>{{wallet.unlimitedUsage?'∞':wallet.available.toLocaleString()}}</strong></div><div class="product-metric">{{t.frozen}}<strong>{{wallet.frozen.toLocaleString()}}</strong></div><div class="product-metric">计费状态<strong style="font-size:20px">{{wallet.unlimitedUsage?'内测不限额度':wallet.billingEnabled?'按配置计费':'平台积分计费关闭'}}</strong></div></div><p class="product-note">平台积分与模型服务商额度分别管理。当前配置自有模型时，服务商仍按原规则计费。积分定价以调用开始时的配置为准。未确认结果的调用会保留预留记录，核查后再结算。</p><p v-if="wallet.unlimitedUsage" class="product-hint">所有内测账号均可不限次使用文本和图像功能，无需购买积分。实际用量仍正常记录。</p><div class="product-grid"><section v-if="!wallet.unlimitedUsage" class="product-card"><h2>{{t.membership}}</h2><div v-for="member in wallet.memberships" :key="member.id"><strong>{{member.title}}</strong><p>{{dates(member.startsAt)}} 至 {{dates(member.endsAt)}}<br>{{sourceName(member.source)}} · 每日可领 {{member.dailyCredits}} 积分</p></div><p v-if="!wallet.memberships.length" class="product-empty">暂无会员权益。内测可以通过兑换码领取。</p><button :disabled="busy" @click="action('/product/growth/daily-claim')">{{t.daily}}</button></section><section v-if="!wallet.unlimitedUsage" class="product-card"><h2>{{t.redeem}}</h2><form @submit.prevent="action('/product/membership/redeem',{code})"><label>权益兑换码<input v-model="code" autocomplete="off" maxlength="100" required minlength="8"></label><button :disabled="busy">兑换积分或会员</button></form><form class="divider" @submit.prevent="action('/product/growth/invite',{code:invite})"><label>内测邀请码<input v-model="invite" autocomplete="off" maxlength="100" required minlength="8"></label><button :disabled="busy">关联邀请并领取奖励</button></form></section><section v-if="!wallet.unlimitedUsage" class="product-card product-span"><h2>可选方案</h2><p v-if="!wallet.payment.enabled" class="product-hint">{{wallet.payment.reason}}</p><p v-if="!products.length" class="product-empty">暂未发布收费方案，当前可继续内测体验。</p><div v-for="product in products" :key="product.id" class="list-item row between"><div><strong>{{product.title}}</strong><p>{{product.credits}} 积分<span v-if="product.memberDays"> · {{product.memberDays}} 天会员</span><br>{{product.currency}} {{(product.amountMinor/100).toFixed(2)}}</p></div><button :disabled="busy||!wallet.payment.enabled" @click="purchase(product)">购买</button></div></section><section class="product-card product-span"><h2>{{t.orders}}</h2><p v-if="!wallet.orders.length" class="product-empty">暂无订单</p><div v-for="order in wallet.orders" :key="order.id" class="list-item"><strong>{{order.product.title}} · {{stateName(order.state)}}</strong><p class="product-note">{{dates(order.createdAt)}} · {{order.environment==='test'?'测试环境':'生产环境'}}<br>订单 {{order.id}}</p><div class="product-actions"><a v-if="order.checkoutUrl&&order.state==='checkout_ready'" :href="order.checkoutUrl" target="_blank" rel="noopener noreferrer" class="inline-link">打开收银台</a><button :disabled="busy" @click="action('/product/orders/'+order.id+'/reconcile')">核查支付状态</button><button v-if="order.provider==='waffo'&&order.product.kind==='member'" :disabled="busy" @click="cancel(order)">停止自动续费</button></div></div></section><section class="product-card product-span"><h2>{{t.ledger}}</h2><div class="product-scroll"><table class="product-table"><caption class="product-note">最近 100 笔流水；冻结是预留，结算才是实际扣除。</caption><thead><tr><th>时间</th><th>类型</th><th>积分</th><th>来源</th></tr></thead><tbody><tr v-for="item in wallet.ledger" :key="item.id"><td>{{dates(item.createdAt)}}</td><td>{{({grant:'发放',hold:'预留',settle:'结算'} as Record<string,string>)[item.kind]||item.kind}}</td><td>{{item.amount>0?'+':''}}{{item.amount}}</td><td>{{sourceName(item.reference)}}</td></tr></tbody></table></div><p v-if="!wallet.ledger.length" class="product-empty">暂无积分流水</p><div v-if="wallet.holds.length" class="divider"><h3>等待核查的预留</h3><p v-for="hold in wallet.holds" :key="hold.id" class="product-note">{{hold.operation}} · {{hold.reserved}} 积分 · {{hold.state==='unknown'?'供应商结果未知':'已预留'}}<br>任务 {{hold.taskId}}</p></div></section></div></template><p v-else>{{t.loading}}</p></div></template>
